1	//! Command-line parsing matching the reference C++ behavior: the first
2	//! user-supplied argument is parsed like glibc `atoi`, defaulting to 7.
3	
4	/// Parse `n` from the first command-line argument.
5	///
6	/// Behavior matches glibc `atoi` on the first user argument:
7	/// - missing argument => 7
8	/// - leading C whitespace skipped (space, \t, \n, \v, \f, \r)
9	/// - optional '+'/'-' sign
10	/// - leading decimal digits consumed
11	/// - no digits => 0
12	/// - digit accumulation saturates to i64::MAX / i64::MIN (strtol-style)
13	/// - result cast/wrapped to i32 via `as i32`
14	///
15	/// Extra arguments are ignored.
16	pub fn parse_n() -> i32 {
17	    let arg = match std::env::args().nth(1) {
18	        Some(a) => a,
19	        None => return 7,
20	    };
21	    atoi(&arg)
22	}
23	
24	fn atoi(s: &str) -> i32 {
25	    let bytes = s.as_bytes();
26	    let mut i = 0;
27	
28	    // glibc isspace(): space, \t, \n, \v, \f, \r
29	    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
30	        i += 1;
31	    }
32	
33	    let mut negative = false;
34	    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
35	        negative = bytes[i] == b'-';
36	        i += 1;
37	    }
38	
39	    // Accumulate like strtol with long saturation (LONG_MAX / LONG_MIN).
40	    let mut value: i64 = 0;
41	    let mut overflowed = false;
42	    while i < bytes.len() && bytes[i].is_ascii_digit() {
43	        if !overflowed {
44	            let digit = (bytes[i] - b'0') as i64;
45	            match value
46	                .checked_mul(10)
47	                .and_then(|v| v.checked_add(digit))
48	            {
49	                Some(v) => value = v,
50	                None => overflowed = true,
51	            }
52	        }
53	        i += 1;
54	    }
55	
56	    if overflowed {
57	        value = i64::MAX;
58	    }
59	
60	    let result: i64 = if negative {
61	        if overflowed {
62	            // strtol returns LONG_MIN on negative overflow.
63	            i64::MIN
64	        } else {
65	            -value
66	        }
67	    } else {
68	        value
69	    };
70	
71	    result as i32
72	}

1	//! Geometry generation: spiral point sequence used as earcut input.
2	
3	use std::f64::consts::PI;
4	
5	/// Build the reference spiral of `2 * n` points.
6	///
7	/// For `i` in `0..2n`:
8	/// - `t = i as f64 / (2n) as f64`
9	/// - `radius = t`
10	/// - `angle = (4.0 * PI) * t`
11	/// - point = `(radius * cos(angle), radius * sin(angle))`
12	///
13	/// Negative or zero `n` yields an empty vector (no points).
14	pub fn spiral(n: i32) -> Vec<[f64; 2]> {
15	    if n <= 0 {
16	        return Vec::new();
17	    }
18	    let count = n * 2;
19	    let denom = count as f64;
20	    let mut points = Vec::with_capacity(count as usize);
21	    for i in 0..count {
22	        let t = i as f64 / denom;
23	        let radius = t;
24	        let angle = (4.0 * PI) * t;
25	        points.push([radius * angle.cos(), radius * angle.sin()]);
26	    }
27	    points
28	}

1	//! Deterministic Mapbox-earcut-style ear clipping triangulation (std-only port).
2	//!
3	//! Single outer ring, no holes. Nodes live in a `Vec` and are referenced by
4	//! `u32` indices (no Rc/RefCell). Follows earcut.js / earcut.hpp semantics:
5	//! z-order hashing kicks in when the flattened coordinate count exceeds 160.
6	
7	use std::ops::{Index, IndexMut};
8	
9	const NULL: u32 = u32::MAX;
10	
11	struct Node {
12	    i: u32, // original vertex index
13	    x: f64,
14	    y: f64,
15	    prev: u32,
16	    next: u32,
17	    z: i32, // 15-bit Morton code (0 until computed)
18	    prev_z: u32,
19	    next_z: u32,
20	    steiner: bool,
21	}
22	
23	// node arena indexed by u32 node ids
24	struct Pool(Vec<Node>);
25	
26	impl Index<u32> for Pool {
27	    type Output = Node;
28	    fn index(&self, id: u32) -> &Node {
29	        &self.0[id as usize]
30	    }
31	}
32	
33	impl IndexMut<u32> for Pool {
34	    fn index_mut(&mut self, id: u32) -> &mut Node {
35	        &mut self.0[id as usize]
36	    }
37	}
38	
39	pub fn earcut(points: &[[f64; 2]]) -> Vec<u32> {
40	    let m = points.len();
41	    let mut triangles: Vec<u32> = Vec::new();
42	    if m == 0 {
43	        return triangles;
44	    }
45	
46	    // Enable z-order hashing when flattened coordinate count > 160 (m > 80).
47	    let (hashing, min_x, min_y, inv_size) = if m * 2 > 160 {
48	        let mut min_x = points[0][0];
49	        let mut max_x = points[0][0];
50	        let mut min_y = points[0][1];
51	        let mut max_y = points[0][1];
52	        for p in &points[1..] {
53	            min_x = min_x.min(p[0]);
54	            max_x = max_x.max(p[0]);
55	            min_y = min_y.min(p[1]);
56	            max_y = max_y.max(p[1]);
57	        }
58	        let mut inv = (max_x - min_x).max(max_y - min_y);
59	        inv = if inv != 0.0 { 32767.0 / inv } else { 0.0 };
60	        (true, min_x, min_y, inv)
61	    } else {
62	        (false, 0.0, 0.0, 0.0)
63	    };
64	
65	    let mut e = Earcut {
66	        nodes: Pool(Vec::with_capacity(m)),
67	    };
68	    if let Some(outer) = e.linked_list(points, true) {
69	        if e.nodes[outer].prev == e.nodes[outer].next {
70	            return triangles;
71	        }
72	        e.earcut_linked(outer, &mut triangles, min_x, min_y, inv_size, 0, hashing);
73	    }
74	    triangles
75	}
76	
77	struct Earcut {
78	    nodes: Pool,
79	}
80	
81	impl Earcut {
82	    // signed area of the ring: sum((x[j]-x[i])*(y[i]+y[j])), j = previous index
83	    fn signed_area(points: &[[f64; 2]]) -> f64 {
84	        let m = points.len();
85	        let mut sum = 0.0f64;
86	        let mut j = m - 1;
87	        for i in 0..m {
88	            sum += (points[j][0] - points[i][0]) * (points[i][1] + points[j][1]);
89	            j = i;
90	        }
91	        sum
92	    }
93	
94	    // create a circular doubly linked list from the ring in source order when
95	    // clockwise == (signed area > 0), otherwise in reverse order
96	    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> Option<u32> {
97	        let m = points.len();
98	        if m == 0 {
99	            return None;
100	        }
101	        let mut last: Option<u32> = None;
102	        if clockwise == (Self::signed_area(points) > 0.0) {
103	            for i in 0..m {
104	                last = Some(self.insert_node(i as u32, points[i][0], points[i][1], last));
105	            }
106	        } else {
107	            for i in (0..m).rev() {
108	                last = Some(self.insert_node(i as u32, points[i][0], points[i][1], last));
109	            }
110	        }
111	        let mut last = last?;
112	        if self.nodes_eq(last, self.nodes[last].next) {
113	            self.remove_node(last);
114	            last = self.nodes[last].next;
115	        }
116	        Some(last)
117	    }
118	
119	    // main loop: slice off ears one by one
120	    #[allow(clippy::too_many_arguments)]
121	    #[allow(unused_assignments)] // final ear/pass assignments mirror the JS reference structure
122	    fn earcut_linked(
123	        &mut self,
124	        ear: u32,
125	        triangles: &mut Vec<u32>,
126	        min_x: f64,
127	        min_y: f64,
128	        inv_size: f64,
129	        pass: u8,
130	        hashing: bool,
131	    ) {
132	        // interlink polygon nodes in z-order on the first (outer) pass
133	        if pass == 0 && inv_size != 0.0 {
134	            self.index_curve(ear, min_x, min_y, inv_size);
135	        }
136	
137	        let mut ear = ear;
138	        let mut stop = ear;
139	        let mut pass = pass;
140	
141	        while self.nodes[ear].prev != self.nodes[ear].next {
142	            let prev = self.nodes[ear].prev;
143	            let next = self.nodes[ear].next;
144	
145	            let is_ear = if hashing {
146	                self.is_ear_hashed(ear, min_x, min_y, inv_size)
147	            } else {
148	                self.is_ear(ear)
149	            };
150	
151	            if is_ear {
152	                triangles.push(self.nodes[prev].i);
153	                triangles.push(self.nodes[ear].i);
154	                triangles.push(self.nodes[next].i);
155	
156	                self.remove_node(ear);
157	
158	                // skipping the next vertex leads to less sliver triangles
159	                ear = self.nodes[next].next;
160	                stop = ear;
161	                continue;
162	            }
163	
164	            ear = next;
165	
166	            // looped through the whole remaining polygon without finding an ear
167	            if ear == stop {
168	                if pass == 0 {
169	                    // try filtering points and slicing again
170	                    ear = self.filter_points(ear, None);
171	                    pass = 1;
172	                } else if pass == 1 {
173	                    // try curing all small self-intersections locally
174	                    let filtered = self.filter_points(ear, None);
175	                    ear = self.cure_local_intersections(filtered, triangles);
176	                    pass = 2;
177	                } else if pass == 2 {
178	                    // last resort: split the remaining polygon in two
179	                    self.split_earcut(ear, triangles, min_x, min_y, inv_size, hashing);
180	                }
181	                break;
182	            }
183	        }
184	    }
185	
186	    // check whether a triangle (prev, ear, next) is an ear; O(n) blocker scan
187	    fn is_ear(&self, ear: u32) -> bool {
188	        let a = self.nodes[ear].prev;
189	        let b = ear;
190	        let c = self.nodes[ear].next;
191	
192	        if self.area(a, b, c) >= 0.0 {
193	            return false; // reflex, can't be an ear
194	        }
195	
196	        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
197	        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
198	        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);
199	
200	        let x0 = ax.min(bx).min(cx);
201	        let y0 = ay.min(by).min(cy);
202	        let x1 = ax.max(bx).max(cx);
203	        let y1 = ay.max(by).max(cy);
204	
205	        let mut p = self.nodes[c].next;
206	        while p != a {
207	            if self.nodes[p].x >= x0
208	                && self.nodes[p].x <= x1
209	                && self.nodes[p].y >= y0
210	                && self.nodes[p].y <= y1
211	                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
212	                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
213	            {
214	                return false;
215	            }
216	            p = self.nodes[p].next;
217	        }
218	        true
219	    }
220	
221	    // z-order hashed variant of the ear check
222	    fn is_ear_hashed(&self, ear: u32, min_x: f64, min_y: f64, inv_size: f64) -> bool {
223	        let a = self.nodes[ear].prev;
224	        let b = ear;
225	        let c = self.nodes[ear].next;
226	
227	        if self.area(a, b, c) >= 0.0 {
228	            return false;
229	        }
230	
231	        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
232	        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
233	        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);
234	
235	        let x0 = ax.min(bx).min(cx);
236	        let y0 = ay.min(by).min(cy);
237	        let x1 = ax.max(bx).max(cx);
238	        let y1 = ay.max(by).max(cy);
239	
240	        let min_z = z_order(x0, y0, min_x, min_y, inv_size);
241	        let max_z = z_order(x1, y1, min_x, min_y, inv_size);
242	
243	        let mut p = self.nodes[ear].prev_z;
244	        let mut n = self.nodes[ear].next_z;
245	
246	        // look for points inside the triangle in both directions
247	        while p != NULL && self.nodes[p].z >= min_z && n != NULL && self.nodes[n].z <= max_z {
248	            if self.nodes[p].x >= x0
249	                && self.nodes[p].x <= x1
250	                && self.nodes[p].y >= y0
251	                && self.nodes[p].y <= y1
252	                && p != a
253	                && p != c
254	                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
255	                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
256	            {
257	                return false;
258	            }
259	            p = self.nodes[p].prev_z;
260	
261	            if self.nodes[n].x >= x0
262	                && self.nodes[n].x <= x1
263	                && self.nodes[n].y >= y0
264	                && self.nodes[n].y <= y1
265	                && n != a
266	                && n != c
267	                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[n].x, self.nodes[n].y)
268	                && self.area(self.nodes[n].prev, n, self.nodes[n].next) >= 0.0
269	            {
270	                return false;
271	            }
272	            n = self.nodes[n].next_z;
273	        }
274	
275	        // look for remaining points in decreasing z-order
276	        while p != NULL && self.nodes[p].z >= min_z {
277	            if self.nodes[p].x >= x0
278	                && self.nodes[p].x <= x1
279	                && self.nodes[p].y >= y0
280	                && self.nodes[p].y <= y1
281	                && p != a
282	                && p != c
283	                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
284	                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
285	            {
286	                return false;
287	            }
288	            p = self.nodes[p].prev_z;
289	        }
290	
291	        // look for remaining points in increasing z-order
292	        while n != NULL && self.nodes[n].z <= max_z {
293	            if self.nodes[n].x >= x0
294	                && self.nodes[n].x <= x1
295	                && self.nodes[n].y >= y0
296	                && self.nodes[n].y <= y1
297	                && n != a
298	                && n != c
299	                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[n].x, self.nodes[n].y)
300	                && self.area(self.nodes[n].prev, n, self.nodes[n].next) >= 0.0
301	            {
302	                return false;
303	            }
304	            n = self.nodes[n].next_z;
305	        }
306	        true
307	    }
308	
309	    // eliminate colinear or duplicate points; returns the new end node
310	    fn filter_points(&mut self, start: u32, end: Option<u32>) -> u32 {
311	        let mut end = end.unwrap_or(start);
312	        let mut p = start;
313	        loop {
314	            let mut again = false;
315	
316	            let pn = self.nodes[p].next;
317	            let pp = self.nodes[p].prev;
318	            if !self.nodes[p].steiner && (self.nodes_eq(p, pn) || self.area(pp, p, pn) == 0.0) {
319	                self.remove_node(p);
320	                p = self.nodes[p].prev;
321	                end = p;
322	
323	                if p == self.nodes[p].next {
324	                    break;
325	                }
326	                again = true;
327	            } else {
328	                p = self.nodes[p].next;
329	            }
330	
331	            if !(again || p != end) {
332	                break;
333	            }
334	        }
335	        end
336	    }
337	
338	    // walk the ring and try to cure small local self-intersections
339	    fn cure_local_intersections(&mut self, start: u32, triangles: &mut Vec<u32>) -> u32 {
340	        let mut start = start;
341	        let mut p = start;
342	        loop {
343	            let a = self.nodes[p].prev;
344	            let pn = self.nodes[p].next;
345	            let b = self.nodes[pn].next;
346	
347	            if !self.nodes_eq(a, b)
348	                && self.intersects(a, p, pn, b)
349	                && self.locally_inside(a, b)
350	                && self.locally_inside(b, a)
351	            {
352	                triangles.push(self.nodes[a].i);
353	                triangles.push(self.nodes[p].i);
354	                triangles.push(self.nodes[b].i);
355	
356	                self.remove_node(p);
357	                let pn = self.nodes[p].next;
358	                self.remove_node(pn);
359	
360	                p = b;
361	                start = b;
362	            }
363	            p = self.nodes[p].next;
364	            if p == start {
365	                break;
366	            }
367	        }
368	        self.filter_points(p, None)
369	    }
370	
371	    // try to find a valid diagonal and split the remaining polygon in two
372	    fn split_earcut(
373	        &mut self,
374	        start: u32,
375	        triangles: &mut Vec<u32>,
376	        min_x: f64,
377	        min_y: f64,
378	        inv_size: f64,
379	        hashing: bool,
380	    ) {
381	        let mut a = start;
382	        loop {
383	            let mut b = self.nodes[self.nodes[a].next].next;
384	            while b != self.nodes[a].prev {
385	                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
386	                    // split the polygon in two by the diagonal
387	                    let c = self.split_polygon(a, b);
388	
389	                    // filter colinear points around the cuts
390	                    let a_next = self.nodes[a].next;
391	                    let a2 = self.filter_points(a, Some(a_next));
392	                    let c_next = self.nodes[c].next;
393	                    let c2 = self.filter_points(c, Some(c_next));
394	
395	                    // run earcut on each half
396	                    self.earcut_linked(a2, triangles, min_x, min_y, inv_size, 0, hashing);
397	                    self.earcut_linked(c2, triangles, min_x, min_y, inv_size, 0, hashing);
398	                    return;
399	                }
400	                b = self.nodes[b].next;
401	            }
402	            a = self.nodes[a].next;
403	            if a == start {
404	                break;
405	            }
406	        }
407	    }
408	
409	    // link two polygon vertices with a bridge, duplicating the endpoints
410	    fn split_polygon(&mut self, a: u32, b: u32) -> u32 {
411	        let a2 = self.duplicate_node(a);
412	        let b2 = self.duplicate_node(b);
413	
414	        let an = self.nodes[a].next;
415	        let bp = self.nodes[b].prev;
416	
417	        self.nodes[a].next = b;
418	        self.nodes[b].prev = a;
419	
420	        self.nodes[a2].next = an;
421	        self.nodes[an].prev = a2;
422	
423	        self.nodes[b2].next = a2;
424	        self.nodes[a2].prev = b2;
425	
426	        self.nodes[bp].next = b2;
427	        self.nodes[b2].prev = bp;
428	
429	        b2
430	    }
431	
432	    fn is_valid_diagonal(&self, a: u32, b: u32) -> bool {
433	        let an = self.nodes[a].next;
434	        let ap = self.nodes[a].prev;
435	        let bn = self.nodes[b].next;
436	        let bp = self.nodes[b].prev;
437	
438	        self.nodes[an].i != self.nodes[b].i
439	            && self.nodes[ap].i != self.nodes[b].i
440	            && !self.intersects_polygon(a, b) // doesn't intersect other edges
441	            && ((self.locally_inside(a, b)
442	                && self.locally_inside(b, a)
443	                && self.middle_inside(a, b) // locally visible
444	                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0)) // no opposite-facing sectors
445	                || (self.nodes_eq(a, b)
446	                    && self.area(ap, a, an) > 0.0
447	                    && self.area(bp, b, bn) > 0.0)) // special zero-length case
448	    }
449	
450	    // signed area of triangle (a, b, c) — Mapbox predicate
451	    fn area(&self, a: u32, b: u32, c: u32) -> f64 {
452	        let pa = &self.nodes[a];
453	        let pb = &self.nodes[b];
454	        let pc = &self.nodes[c];
455	        (pb.y - pa.y) * (pc.x - pb.x) - (pb.x - pa.x) * (pc.y - pb.y)
456	    }
457	
458	    fn nodes_eq(&self, p1: u32, p2: u32) -> bool {
459	        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
460	    }
461	
462	    // check if the polygon vertex a is locally inside relative to diagonal (a, b)
463	    fn locally_inside(&self, a: u32, b: u32) -> bool {
464	        let ap = self.nodes[a].prev;
465	        let an = self.nodes[a].next;
466	        if self.area(ap, a, an) < 0.0 {
467	            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
468	        } else {
469	            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
470	        }
471	    }
472	
473	    // check if the middle point of diagonal (a, b) is inside the polygon
474	    fn middle_inside(&self, a: u32, b: u32) -> bool {
475	        let mut p = a;
